-- pos-workorder: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.approval_configuration (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    approval_window_days integer,
    decline_expiry_days integer,
    priority integer,
    require_signature boolean,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    customer_id uuid,
    id uuid NOT NULL,
    location_id uuid,
    approval_method character varying(255),
    CONSTRAINT approval_configuration_approval_method_check CHECK (((approval_method)::text = ANY (ARRAY[('CLICK_CONFIRM'::character varying)::text, ('SIGNATURE'::character varying)::text, ('ELECTRONIC_SIGNATURE'::character varying)::text, ('VERBAL_CONFIRMATION'::character varying)::text])))
);

CREATE TABLE public.approval_record (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    resolved_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    change_request_id uuid NOT NULL,
    id uuid NOT NULL,
    workorder_id uuid NOT NULL,
    approval_note text,
    exception_reason text,
    resolution_status character varying(255) NOT NULL,
    resolved_by character varying(255) NOT NULL,
    CONSTRAINT approval_record_resolution_status_check CHECK (((resolution_status)::text = ANY (ARRAY[('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text, ('APPROVED_WITH_EXCEPTION'::character varying)::text])))
);

CREATE TABLE public.audit_events (
