    CONSTRAINT change_request_status_check CHECK (((status)::text = ANY (ARRAY[('AWAITING_ADVISOR_REVIEW'::character varying)::text, ('APPROVED'::character varying)::text, ('DECLINED'::character varying)::text, ('CANCELLED'::character varying)::text, ('APPROVED_WITH_EXCEPTION'::character varying)::text])))
);

