CREATE TABLE public.estimate (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    subtotal numeric(38,2),
    tax_amount numeric(38,2),
    total numeric(38,2),
    version integer,
    approved_at timestamp(6) without time zone,
    created_at timestamp(6) with time zone NOT NULL,
    declined_at timestamp(6) without time zone,
    expires_at timestamp(6) without time zone,
    submitted_at timestamp(6) without time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid,
    approval_configuration_id uuid,
    approved_by uuid,
    customer_id uuid,
    id uuid NOT NULL,
    location_id uuid,
    vehicle_id uuid,
    crm_party_id character varying(36),
    crm_vehicle_id character varying(36),
    purchase_order_number character varying(100),
    signature_data character varying(100000),
    approval_notes character varying(255),
    created_by_id character varying(255) NOT NULL,
    created_by_user_id character varying(255),
    crm_contact_ids text,
    currency_uom_id character varying(255),
    decline_reason character varying(255),
    estimate_number character varying(255),
    signature_mime_type character varying(255),
    signer_name character varying(255),
    status character varying(255),
    submitted_by character varying(255),
    tax_pending boolean DEFAULT false NOT NULL,
    aggregate_version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT estimate_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('PENDING_APPROVAL'::character varying)::text, ('OPEN'::character varying)::text, ('PENDING_CUSTOMER'::character varying)::text, ('APPROVED'::character varying)::text, ('DECLINED'::character varying)::text, ('EXPIRED'::character varying)::text, ('SCHEDULED'::character varying)::text, ('INVOICED'::character varying)::text, ('CANCELLED'::character varying)::text, ('ARCHIVED'::character varying)::text])))
);

CREATE TABLE public.estimate_item (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
