    line_total numeric(19,2),
    quantity numeric(19,4) NOT NULL,
    unit_price numeric(19,2) NOT NULL,
    approval_timestamp timestamp(6) without time zone,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    approval_proof_id uuid,
    estimate_id uuid NOT NULL,
    id uuid NOT NULL,
    product_id uuid,
    service_id uuid,
    approval_status character varying(20),
    item_type character varying(20) NOT NULL,
    tax_code character varying(50),
    approval_method_used character varying(100),
    description character varying(500),
    approval_notes character varying(1000),
    rejection_reason character varying(1000),
    created_by_id character varying(255) NOT NULL,
    uom_code character varying(32),
    guide_hours numeric(5,1),
    guide_source_code character varying(32),
    guide_source_revision character varying(64),
    guide_match_grade character varying(24),
    guide_overlap_group character varying(64),
    guide_included_op_codes text,
    rate_hourly numeric(10,4),
