    CONSTRAINT estimate_item_approval_status_check CHECK (((approval_status)::text = ANY (ARRAY[('PENDING_APPROVAL'::character varying)::text, ('APPROVED'::character varying)::text, ('DECLINED'::character varying)::text]))),
    CONSTRAINT estimate_item_item_type_check CHECK (((item_type)::text = ANY (ARRAY[('PART'::character varying)::text, ('LABOR'::character varying)::text])))
