    CONSTRAINT travel_segment_segment_type_check CHECK (((segment_type)::text = ANY (ARRAY[('DEPART_SHOP'::character varying)::text, ('ARRIVE_CUSTOMER_SITE'::character varying)::text, ('DEPART_CUSTOMER_SITE'::character varying)::text, ('ARRIVE_SHOP'::character varying)::text, ('TRAVEL_BETWEEN_SITES'::character varying)::text, ('DEADHEAD'::character varying)::text]))),
