);

CREATE TABLE public.work_session (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    locked boolean NOT NULL,
    overlap_override_used boolean NOT NULL,
    total_duration_seconds integer NOT NULL,
    approved_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    end_at timestamp(6) with time zone,
    locked_at timestamp(6) with time zone,
    override_at timestamp(6) with time zone,
    start_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    location_id uuid NOT NULL,
    mechanic_id uuid NOT NULL,
    resource_id uuid,
    work_order_id uuid NOT NULL,
    work_order_task_id uuid NOT NULL,
    work_session_id uuid NOT NULL,
    approval_notes text,
    approved_by_user_id character varying(255),
    overridden_by_user_id character varying(255),
    override_reason text,
    status character varying(255) NOT NULL,
    CONSTRAINT work_session_status_check CHECK (((status)::text = ANY (ARRAY[('IN_PROGRESS'::character varying)::text, ('COMPLETED'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text])))
);

CREATE TABLE public.workorder (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    is_reopened boolean,
    scheduled_date date,
    approved_at timestamp(6) with time zone,
    completed_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    reopened_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    work_started_at timestamp(6) with time zone,
    approval_id uuid,
    customer_id uuid,
    estimate_id uuid,
    id uuid NOT NULL,
    invoice_id uuid,
    location_id uuid,
    resource_id uuid,
    shop_id uuid,
    vehicle_id uuid,
    crm_party_id character varying(36),
    crm_vehicle_id character varying(36),
    signature_data character varying(100000),
    approval_notes character varying(255),
    completed_by character varying(255),
    completion_notes text,
    crm_contact_ids text,
    mechanic_ids text,
    operational_context_version character varying(255),
    reopen_reason text,
    reopened_by character varying(255),
    required_certifications text,
    signature_mime_type character varying(255),
    signer_name character varying(255),
    status character varying(255),
    workorder_number character varying(64) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    resource_type character varying(32),
    CONSTRAINT workorder_resource_type_check CHECK (((resource_type IS NULL) OR ((resource_type)::text = ANY ((ARRAY['BAY'::character varying, 'MOBILE_UNIT'::character varying])::text[])))),
    CONSTRAINT workorder_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('APPROVED'::character varying)::text, ('ASSIGNED'::character varying)::text, ('WORK_IN_PROGRESS'::character varying)::text, ('AWAITING_PARTS'::character varying)::text, ('AWAITING_APPROVAL'::character varying)::text, ('READY_FOR_PICKUP'::character varying)::text, ('COMPLETED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.workorder_fleet_authorization (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    workorder_fleet_authorization_id uuid NOT NULL,
    workorder_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    vendor_profile_id uuid,
    status character varying(20) NOT NULL,
    vendor_reason_code character varying(50),
    vendor_reason_text character varying(1000),
    review_reason character varying(1000),
    contract_reference character varying(100),
    authorized_amount numeric(19,4),
    currency character varying(3),
    resolution character varying(30),
    resolution_reason character varying(1000),
    resolved_by character varying(100),
    resolved_at timestamp(6) with time zone,
    requested_at timestamp(6) with time zone,
    decided_at timestamp(6) with time zone,
    first_blocked_at timestamp(6) with time zone,
    resources_released_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(100),
    updated_by character varying(100),
    CONSTRAINT ck_wfa_amount_currency CHECK (((authorized_amount IS NULL) OR (currency IS NOT NULL))),
    CONSTRAINT ck_wfa_resolution CHECK (((resolution IS NULL) OR ((resolution)::text = ANY ((ARRAY['SCOPE_REVISED'::character varying, 'CANCELLED'::character varying])::text[])))),
    CONSTRAINT ck_wfa_status CHECK (((status)::text = ANY ((ARRAY['NOT_REQUESTED'::character varying, 'PENDING'::character varying, 'GRANTED'::character varying, 'REFUSED'::character varying, 'MANUAL_REVIEW'::character varying, 'CANCELLED'::character varying])::text[])))
);

CREATE TABLE public.workorder_labor_entry (
