);

CREATE TABLE public.workorder_part (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    customer_denial_acknowledged boolean,
    declined boolean,
    is_emergency_safety boolean,
    is_substituted boolean NOT NULL,
    line_total numeric(19,2),
    photo_not_possible boolean,
    quantity numeric(19,4),
    quantity_consumed numeric(19,4),
    quantity_issued numeric(19,4),
    quantity_returned numeric(19,4),
    unit_price numeric(19,2),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    change_request_id uuid,
    id uuid NOT NULL,
    non_inventory_product_entity_id uuid,
    origin_estimate_item_id uuid,
    original_product_id uuid,
    product_entity_id uuid,
    work_order_id uuid,
    work_order_service_id uuid,
    price_lock_status character varying(20) NOT NULL,
    tax_code character varying(50),
    description character varying(500),
    emergency_notes text,
    photo_evidence_url character varying(255),
    status character varying(255),
    returnable boolean,
    reservation_id uuid,
    backorder_id uuid,
    uom_code character varying(32),
    CONSTRAINT ck_workorder_part_has_reference CHECK (((work_order_service_id IS NOT NULL) OR (work_order_id IS NOT NULL))),
    CONSTRAINT workorder_part_price_lock_status_check CHECK (((price_lock_status)::text = ANY (ARRAY[('LOCKED'::character varying)::text, ('UNLOCKED'::character varying)::text]))),
    CONSTRAINT workorder_part_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING_APPROVAL'::character varying)::text, ('OPEN'::character varying)::text, ('READY_TO_EXECUTE'::character varying)::text, ('IN_PROGRESS'::character varying)::text, ('COMPLETED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

